#!/usr/bin/python3
import html,json,os,secrets
from http import cookies
from http.server import BaseHTTPRequestHandler,ThreadingHTTPServer
from pathlib import Path
from urllib.parse import parse_qs,urlparse

STATE_DIR=Path('/var/lib/harbor-service'); STATE_FILE=STATE_DIR/'relaydesk-state.json'
INCIDENTS={
'INC-4798':{'customer':'Lumen Bakery','title':'Receipt emails delayed','queue':'Standard','error':'MAIL-208'},
'INC-4813':{'customer':'Northstar Dental','title':'Appointment reminders duplicated','queue':'Priority customers','error':'MSG-022'},
'INC-4821':{'customer':'Northstar Dental','title':'Radiograph uploads rejected','queue':'Priority customers','error':'STO-413'},
'INC-4830':{'customer':'Juniper Fitness','title':'Member exports time out','queue':'Priority customers','error':'JOB-504'}}
DEFAULT={k:{**v,'owner':'Unassigned','severity':'Medium','status':'New','note':''} for k,v in INCIDENTS.items()}; SESSIONS={}
def load(): return json.loads(STATE_FILE.read_text())
def save(state):
 p=STATE_FILE.with_suffix('.tmp'); p.write_text(json.dumps(state,sort_keys=True,indent=2)+'\n'); os.replace(p,STATE_FILE)
def page(title,content):
 return f'''<!doctype html><html><head><meta charset="utf-8"><title>{html.escape(title)} · RelayDesk</title><style>
body{{margin:0;background:#f3f6fa;color:#172033;font:16px system-ui,sans-serif}}header{{background:#14213d;color:white;padding:20px 34px;display:flex;justify-content:space-between}}main{{max-width:980px;margin:28px auto;padding:0 24px}}.card{{display:block;background:white;border:1px solid #d8dfeb;border-radius:10px;padding:18px;margin:12px 0;color:inherit;text-decoration:none;box-shadow:0 2px 7px #14213d10}}.pill{{background:#e7eef9;border-radius:99px;padding:5px 10px;font-size:13px}}button,.button{{display:inline-block;background:#1769e0;color:white;border:0;border-radius:7px;padding:11px 16px;text-decoration:none;font-weight:650;cursor:pointer}}.row{{display:flex;gap:12px;align-items:center;flex-wrap:wrap}}label.choice{{border:1px solid #bac6d8;border-radius:8px;padding:10px 13px;background:white}}textarea{{width:100%;min-height:90px;padding:10px;box-sizing:border-box}}dt{{font-size:13px;color:#64748b}}dd{{margin:3px 0 15px}}.flash{{background:#dcfce7;border:1px solid #86efac;padding:12px;border-radius:8px}}</style></head><body><header><b>RelayDesk</b><span>After-hours workspace</span></header><main>{content}</main></body></html>'''.encode()
class Handler(BaseHTTPRequestHandler):
 def log_message(self,*_): pass
 def reply(self,code,body,ctype='text/html; charset=utf-8',headers=()):
  self.send_response(code); self.send_header('Content-Type',ctype); self.send_header('Content-Length',str(len(body)))
  for k,v in headers:self.send_header(k,v)
  self.end_headers();self.wfile.write(body)
 def session(self):
  jar=cookies.SimpleCookie(self.headers.get('Cookie','')); item=jar.get('relay_session')
  if item and item.value in SESSIONS:return item.value,False
  sid=secrets.token_urlsafe(18);SESSIONS[sid]={'visited':[],'csrf':secrets.token_urlsafe(18)};return sid,True
 def do_GET(self):
  path=urlparse(self.path).path
  if path=='/health':return self.reply(200,b'relaydesk-ready-v1','text/plain')
  sid,fresh=self.session();headers=[('Set-Cookie',f'relay_session={sid}; Path=/; HttpOnly; SameSite=Strict')] if fresh else [];state=load()
  if path=='/': body=page('Home','<h1>Incident operations</h1><p>Review and route customer-impacting incidents.</p><a id="open-queues" class="button" href="/queues">Open queues</a>')
  elif path=='/queues': body=page('Queues','<h1>Queues</h1><div class="card"><h2>Priority customers</h2><p>3 open incidents</p><a id="priority-queue" class="button" href="/incidents?queue=priority">View queue</a></div><div class="card"><h2>Standard</h2><p>1 open incident</p></div>')
  elif path=='/incidents':
   cards=[]
   for key,x in state.items():
    if x['queue']=='Priority customers':cards.append(f'<a class="card incident" id="incident-{key.lower()}" href="/incident/{key}"><span class="pill">{key}</span><h2>{html.escape(x["customer"])}</h2><p>{html.escape(x["title"])}</p></a>')
   body=page('Priority customers','<a href="/queues">← Queues</a><h1>Priority customers</h1>'+''.join(cards))
  elif path.startswith('/incident/'):
   key=path.rsplit('/',1)[-1]
   if key not in state:return self.reply(404,b'not found','text/plain')
   SESSIONS[sid]['visited'].append(key);x=state[key]
   body=page(key,f'<a href="/incidents?queue=priority">← Priority customers</a><h1>{key}: {html.escape(x["title"])}</h1><div class="card"><dl><dt>Customer</dt><dd>{html.escape(x["customer"])}</dd><dt>Reported impact</dt><dd>Staff cannot upload radiographs to patient records.</dd><dt>Error signature</dt><dd>{html.escape(x["error"])}</dd><dt>Owner</dt><dd>{html.escape(x["owner"])}</dd><dt>Severity</dt><dd>{html.escape(x["severity"])}</dd><dt>Status</dt><dd>{html.escape(x["status"])}</dd></dl><a id="edit-incident" class="button" href="/edit/{key}">Edit triage</a></div>')
  elif path.startswith('/edit/'):
   key=path.rsplit('/',1)[-1]
   if key not in state or key not in SESSIONS[sid]['visited']:return self.reply(403,b'Open incident details first','text/plain')
   x=state[key];csrf=SESSIONS[sid]['csrf']
   def choices(name,vals):return '<div class="row">'+''.join(f'<label class="choice" id="choose-{name}-{v.lower().replace(" ","-")}"><input type="radio" name="{name}" value="{v}" {"checked" if x[name]==v else ""}> {v}</label>' for v in vals)+'</div>'
   form=f'<a href="/incident/{key}">← Incident</a><h1>Edit triage: {key}</h1><form method="post" action="/save/{key}"><input type="hidden" name="csrf" value="{csrf}"><h3>Owner</h3>{choices("owner",["Unassigned","Mira Chen","Dante Ruiz"])}<h3>Severity</h3>{choices("severity",["Low","Medium","High","Critical"])}<h3>Status</h3>{choices("status",["New","Investigating","Escalated","Resolved"])}<h3><label for="note">Internal note</label></h3><textarea id="note" name="note">{html.escape(x["note"])}</textarea><p><button id="save-triage" type="submit">Save triage</button></p></form>';body=page('Edit triage',form)
  else:return self.reply(404,b'not found','text/plain')
  self.reply(200,body,headers=headers)
 def do_POST(self):
  path=urlparse(self.path).path;sid,_=self.session()
  if not path.startswith('/save/'):return self.reply(404,b'not found','text/plain')
  key=path.rsplit('/',1)[-1];data=parse_qs(self.rfile.read(int(self.headers.get('Content-Length','0'))).decode())
  if key not in INCIDENTS or key not in SESSIONS[sid]['visited'] or data.get('csrf',[''])[0]!=SESSIONS[sid]['csrf']:return self.reply(403,b'Invalid workflow session','text/plain')
  vals={n:data.get(n,[''])[0] for n in ('owner','severity','status','note')}
  if vals['owner'] not in ('Unassigned','Mira Chen','Dante Ruiz') or vals['severity'] not in ('Low','Medium','High','Critical') or vals['status'] not in ('New','Investigating','Escalated','Resolved') or len(vals['note'])>240:return self.reply(400,b'Invalid form values','text/plain')
  state=load();state[key].update(vals);state[key]['revision']=state[key].get('revision',0)+1;save(state)
  self.reply(200,page('Saved',f'<div class="flash" id="saved-message">Triage update saved for {key}.</div><p><a id="return-incident" class="button" href="/incident/{key}">Return to incident</a></p>'))
if __name__=='__main__':
 STATE_DIR.mkdir(parents=True,exist_ok=True)
 if not STATE_FILE.exists():save(DEFAULT)
 ThreadingHTTPServer(('127.0.0.1',8099),Handler).serve_forever()
